import httpx
from starlette.applications import Starlette
from starlette.responses import PlainTextResponse
from starlette.routing import Route

UPSTREAMS = {
    "status": "https://status.example.com/api/summary",
    "docs": "https://docs.example.com/api/index",
}


async def preview(request):
    target = UPSTREAMS.get(request.query_params.get("source", ""))
    if target is None:
        return PlainTextResponse("unknown source", status_code=400)
    async with httpx.AsyncClient() as client:
        upstream = await client.get(target)
    return PlainTextResponse(upstream.text[:2000])


app = Starlette(routes=[Route("/preview", preview)])

const express = require("express");
const { Pool } = require("pg");

const pool = new Pool();
const app = express();

app.get("/users", async (req, res) => {
  const result = await pool.query("SELECT id, email FROM users WHERE role = '" + req.query.role + "'");
  res.json(result.rows);
});

app.listen(3000);

