const express = require("express");
const path = require("path");
const app = express();

const DOCS = path.join(__dirname, "documents");
const FILES = { terms: "terms.pdf", privacy: "privacy.pdf" };

app.get("/document", (req, res) => {
  const file = FILES[req.query.doc];
  if (!file) {
    return res.status(404).end();
  }
  res.sendFile(path.join(DOCS, file));
});

app.listen(3000);

