const express = require("express");
const axios = require("axios");
const app = express();

const FEEDS = {
  news: "https://feeds.example.com/news.json",
  releases: "https://feeds.example.com/releases.json",
};

app.get("/feed", async (req, res) => {
  const feed = FEEDS[req.query.name];
  if (!feed) {
    return res.status(400).end();
  }
  const upstream = await axios.get(feed);
  res.json(upstream.data);
});

app.listen(3000);

