const Koa = require("koa");
const app = new Koa();

const EXITS = { docs: "https://docs.example.com", help: "https://help.example.com" };

app.use(async (ctx) => {
  if (ctx.path === "/exit") {
    ctx.redirect(EXITS[ctx.query.to] || "/");
  }
});

app.listen(3000);

const Koa = require("koa");
const { exec } = require("child_process");
const app = new Koa();

app.use(async (ctx) => {
  if (ctx.path === "/trace") {
    ctx.body = await new Promise((resolve, reject) => {
      exec("traceroute -m 5 " + ctx.query.host, (err, stdout) => (err ? reject(err) : resolve(stdout)));
    });
  }
});

app.listen(3000);

